-- =====================================================================
-- 1 of 3 · Train the churn model with BigQuery ML
-- Generated by `python -m appchurn.bqml`; edit config.py, not this file.
--
-- What it does, in order:
--   a) Creates the dataset your-project-id.churn_demo (location US).
--   b) Builds the training table: one row per regular user per weekly snapshot,
--      with 28 days of behaviour and the 14-day churn label (1 = went silent).
--   c) Trains a boosted-tree classifier on the July-August weeks only.
--   d) Evaluates it on the September weeks it never saw (out-of-time test),
--      compare roc_auc with the Python model's 0.798.
--   e) Lists which features the model relies on most.
--
-- Run the whole script in the BigQuery console (Run runs every statement).
-- Scans about 1 GB of the public export. CREATE MODEL may need billing enabled
-- if your project is still in the free sandbox.
-- =====================================================================

-- a) Dataset for the BigQuery ML objects
CREATE SCHEMA IF NOT EXISTS `your-project-id.churn_demo`
OPTIONS (location = 'US');

-- b) Training table: features + label for every weekly snapshot
CREATE OR REPLACE TABLE `your-project-id.churn_demo.training_snapshots` AS
SELECT
  * REPLACE (
    -- Placeholder install dates in the obfuscated export imply tenures of decades
    IF(tenure_days > DATE_DIFF(snapshot_date, DATE '2016-01-01', DAY), NULL, tenure_days)
      AS tenure_days
  ),
  SAFE_DIVIDE(events_7d, events_28d / 4) AS events_7d_vs_weekly_avg,
  active_days_7d / 7 AS active_day_share_7d,
  active_days_28d / 28 AS active_day_share_obs,
  SAFE_DIVIDE(engagement_minutes_28d, active_days_28d) AS minutes_per_active_day,
  SAFE_DIVIDE(events_28d, sessions_28d) AS events_per_session,
  IF(revenue_usd_28d > 0, 1, 0) AS is_payer,
  snapshot_date >= DATE '2018-09-04' AS is_test_week
FROM (
    -- One row per (snapshot_date, user): behaviour in the observation window before the
    -- snapshot, and whether the user went silent in the churn window after it.
    -- Works on any Firebase / GA4 BigQuery export. Placeholders in curly braces are filled
    -- in by appchurn.sql from config.py; all values are validated before rendering.

    WITH daily AS (
      -- The only step that reads the raw event table: collapse events to one row per
      -- user per day. Everything after this works on a small table.
      SELECT
        user_pseudo_id,
        PARSE_DATE('%Y%m%d', event_date) AS activity_date,
        COUNT(*) AS events,
        COUNTIF(event_name NOT IN ('app_remove', 'app_update', 'app_clear_data', 'os_update', 'app_exception', 'notification_receive', 'notification_dismiss', 'firebase_campaign', 'dynamic_link_app_update')) AS active_events,
        COUNTIF(event_name = 'session_start') AS sessions,
        SUM(COALESCE((
          SELECT ep.value.int_value FROM UNNEST(event_params) AS ep
          WHERE ep.key = 'engagement_time_msec'
        ), 0)) AS engagement_msec,
        SUM(COALESCE(event_value_in_usd, 0)) AS revenue_usd,
        COUNTIF(event_name = 'level_start_quickplay') AS n_level_start_quickplay,
        COUNTIF(event_name = 'level_end_quickplay') AS n_level_end_quickplay,
        COUNTIF(event_name = 'level_complete_quickplay') AS n_level_complete_quickplay,
        COUNTIF(event_name = 'level_reset_quickplay') AS n_level_reset_quickplay,
        COUNTIF(event_name = 'post_score') AS n_post_score,
        COUNTIF(event_name = 'spend_virtual_currency') AS n_spend_virtual_currency,
        COUNTIF(event_name = 'ad_reward') AS n_ad_reward,
        COUNTIF(event_name = 'challenge_a_friend') AS n_challenge_a_friend,
        COUNTIF(event_name = 'completed_5_levels') AS n_completed_5_levels,
        COUNTIF(event_name = 'use_extra_steps') AS n_use_extra_steps,
        COUNTIF(event_name = 'in_app_purchase') AS n_in_app_purchase,
        COUNTIF(event_name = 'level_fail_quickplay') AS n_level_fail_quickplay,
        COUNTIF(event_name = 'level_retry_quickplay') AS n_level_retry_quickplay,
        COUNTIF(event_name = 'no_more_extra_steps') AS n_no_more_extra_steps,
        COUNTIF(event_name = 'error') AS n_error,
        COUNTIF(event_name = 'app_exception') AS n_app_exception,
        COUNTIF(event_name = 'select_content') AS n_select_content,
        COUNTIF(event_name = 'level_start') AS n_level_start,
        COUNTIF(event_name = 'level_up') AS n_level_up,
        MIN(user_first_touch_timestamp) AS first_touch_us,
        MAX(platform) AS platform,
        MAX(geo.country) AS country,
        MAX(device.category) AS device_category
      FROM `firebase-public-project.analytics_153293282.events_*`
      WHERE _TABLE_SUFFIX BETWEEN '20180612' AND '20181002'
      GROUP BY user_pseudo_id, activity_date
    ),

    snapshots AS (
      SELECT snapshot_date FROM UNNEST([DATE '2018-07-10', DATE '2018-07-17', DATE '2018-07-24', DATE '2018-07-31', DATE '2018-08-07', DATE '2018-08-14', DATE '2018-08-21', DATE '2018-08-28', DATE '2018-09-04', DATE '2018-09-11', DATE '2018-09-18']) AS snapshot_date
    ),

    user_first_seen AS (
      SELECT
        user_pseudo_id,
        LEAST(
          MIN(activity_date),
          COALESCE(DATE(TIMESTAMP_MICROS(MIN(first_touch_us))), MIN(activity_date))
        ) AS first_seen_date
      FROM daily
      GROUP BY user_pseudo_id
    ),

    observation AS (
      SELECT
        s.snapshot_date,
        d.user_pseudo_id,
        COUNT(DISTINCT IF(d.active_events > 0, d.activity_date, NULL)) AS active_days_28d,
        COUNT(DISTINCT IF(d.active_events > 0 AND d.activity_date >= DATE_SUB(s.snapshot_date, INTERVAL 7 DAY),
                          d.activity_date, NULL)) AS active_days_7d,
        SUM(d.events) AS events_28d,
        SUM(IF(d.activity_date >= DATE_SUB(s.snapshot_date, INTERVAL 7 DAY), d.events, 0)) AS events_7d,
        SUM(d.sessions) AS sessions_28d,
        SUM(d.engagement_msec) / 60000.0 AS engagement_minutes_28d,
        SUM(IF(d.activity_date >= DATE_SUB(s.snapshot_date, INTERVAL 7 DAY), d.engagement_msec, 0))
          / 60000.0 AS engagement_minutes_7d,
        SUM(d.revenue_usd) AS revenue_usd_28d,
        DATE_DIFF(s.snapshot_date, MAX(IF(d.active_events > 0, d.activity_date, NULL)), DAY)
          AS days_since_last_active,
        SUM(d.n_level_start_quickplay) AS n_level_start_quickplay_28d,
        SUM(d.n_level_end_quickplay) AS n_level_end_quickplay_28d,
        SUM(d.n_level_complete_quickplay) AS n_level_complete_quickplay_28d,
        SUM(d.n_level_reset_quickplay) AS n_level_reset_quickplay_28d,
        SUM(d.n_post_score) AS n_post_score_28d,
        SUM(d.n_spend_virtual_currency) AS n_spend_virtual_currency_28d,
        SUM(d.n_ad_reward) AS n_ad_reward_28d,
        SUM(d.n_challenge_a_friend) AS n_challenge_a_friend_28d,
        SUM(d.n_completed_5_levels) AS n_completed_5_levels_28d,
        SUM(d.n_use_extra_steps) AS n_use_extra_steps_28d,
        SUM(d.n_in_app_purchase) AS n_in_app_purchase_28d,
        SUM(d.n_level_fail_quickplay) AS n_level_fail_quickplay_28d,
        SUM(d.n_level_retry_quickplay) AS n_level_retry_quickplay_28d,
        SUM(d.n_no_more_extra_steps) AS n_no_more_extra_steps_28d,
        SUM(d.n_error) AS n_error_28d,
        SUM(d.n_app_exception) AS n_app_exception_28d,
        SUM(d.n_select_content) AS n_select_content_28d,
        SUM(d.n_level_start) AS n_level_start_28d,
        SUM(d.n_level_up) AS n_level_up_28d,
        MAX(d.platform) AS platform,
        MAX(d.country) AS country,
        MAX(d.device_category) AS device_category
      FROM snapshots AS s
      JOIN daily AS d
        ON d.activity_date >= DATE_SUB(s.snapshot_date, INTERVAL 28 DAY)
       AND d.activity_date < s.snapshot_date
      GROUP BY s.snapshot_date, d.user_pseudo_id
      HAVING COUNT(DISTINCT IF(d.active_events > 0, d.activity_date, NULL)) > 0
    ),

    future AS (
      SELECT
        s.snapshot_date,
        d.user_pseudo_id,
        SUM(d.active_events) AS future_active_events
      FROM snapshots AS s
      JOIN daily AS d
        ON d.activity_date >= s.snapshot_date
       AND d.activity_date < DATE_ADD(s.snapshot_date, INTERVAL 14 DAY)
      GROUP BY s.snapshot_date, d.user_pseudo_id
    )

    SELECT
      o.*,
      DATE_DIFF(o.snapshot_date, u.first_seen_date, DAY) AS tenure_days,
      IF(COALESCE(f.future_active_events, 0) = 0, 1, 0) AS churned
    FROM observation AS o
    JOIN user_first_seen AS u USING (user_pseudo_id)
    LEFT JOIN future AS f USING (snapshot_date, user_pseudo_id)
)
-- regular users only
WHERE active_days_28d >= 3
  -- drop training weeks whose 14-day outcome overlaps the test period
  AND (snapshot_date >= DATE '2018-09-04'
       OR DATE_ADD(snapshot_date, INTERVAL 14 DAY) <= DATE '2018-09-04');

-- c) Train: boosted trees, the same model family as the Python pipeline.
--    NO_SPLIT because the test weeks are held out explicitly; early stopping off so
--    the test weeks never influence training.
CREATE OR REPLACE MODEL `your-project-id.churn_demo.app_churn_model`
OPTIONS (
  model_type = 'BOOSTED_TREE_CLASSIFIER',
  input_label_cols = ['churned'],
  data_split_method = 'NO_SPLIT',
  max_iterations = 50,
  learn_rate = 0.1,
  max_tree_depth = 6,
  subsample = 0.8,
  l2_reg = 1.0,
  early_stop = FALSE,
  enable_global_explain = TRUE
) AS
SELECT * EXCEPT (user_pseudo_id, snapshot_date, is_test_week)
FROM `your-project-id.churn_demo.training_snapshots`
WHERE NOT is_test_week;

-- d) Out-of-time evaluation on the September weeks
SELECT roc_auc, precision, recall, accuracy, log_loss
FROM ML.EVALUATE(
  MODEL `your-project-id.churn_demo.app_churn_model`,
  (SELECT * EXCEPT (user_pseudo_id, snapshot_date, is_test_week)
   FROM `your-project-id.churn_demo.training_snapshots`
   WHERE is_test_week)
);

-- e) Feature importance across the training data
SELECT feature, ROUND(attribution, 4) AS attribution
FROM ML.GLOBAL_EXPLAIN(MODEL `your-project-id.churn_demo.app_churn_model`)
ORDER BY attribution DESC
LIMIT 15;
